<div class="mb-3"><h2 class="fw-bold">Recherche globale</h2><form class="d-flex gap-2" style="max-width:700px"><input class="form-control form-control-lg" name="q" value="<?=e($q)?>" placeholder="Produit, code-barres, client, commande ou ticket"><button class="btn btn-km">Rechercher</button></form></div><?php if($q!==''):?><div class="row g-3"><div class="col-lg-6"><div class="km-card p-3"><h5>Produits</h5><?php foreach($products as $x):?><a class="d-block border-bottom py-2 text-decoration-none text-dark" href="<?=e(base_url('products/'.$x['id'].'/edit'))?>"><strong><?=e($x['name'])?></strong> <span class="text-muted"><?=e($x['internal_code'])?></span></a><?php endforeach;?></div></div><div class="col-lg-6"><div class="km-card p-3"><h5>Clients</h5><?php foreach($customers as $x):?><a class="d-block border-bottom py-2 text-decoration-none text-dark" href="<?=e(base_url('customers/'.$x['id']))?>"><strong><?=e($x['first_name'].' '.$x['last_name'])?></strong> <span class="text-muted"><?=e($x['code'].' '.$x['phone'])?></span></a><?php endforeach;?></div></div><div class="col-lg-6"><div class="km-card p-3"><h5>Commandes</h5><?php foreach($orders as $x):?><a class="d-flex justify-content-between border-bottom py-2 text-decoration-none text-dark" href="<?=e(base_url('orders/'.$x['id']))?>"><span><?=e($x['order_no'].' · '.$x['status'])?></span><strong><?=money($x['total'])?></strong></a><?php endforeach;?></div></div><div class="col-lg-6"><div class="km-card p-3"><h5>Tickets / ventes</h5><?php foreach($sales as $x):?><a class="d-flex justify-content-between border-bottom py-2 text-decoration-none text-dark" href="<?=e(base_url('sales/'.$x['id']))?>"><span><?=e($x['sale_no'].' · '.$x['status'])?></span><strong><?=money($x['total'])?></strong></a><?php endforeach;?></div></div></div><?php endif;?>
